void wall_draw_base(uint16_t *buffer, int wall_screen_y, uint64_t hp, uint64_t max_hp) {
    if (!buffer) return;

    // 1. Blit Wall Base Bitmap with transparency (0x0000 = ground shows through)
    for (int y = 0; y < WALL_HEIGHT; y++) {
        int py = wall_screen_y + y;
        if (py < 0 || py >= SCREEN_H) continue;
        uint16_t *dst = &buffer[py * SCREEN_W];
        const uint16_t *src = &c_wall_bitmap[y * WALL_WIDTH];
        for (int x = 0; x < SCREEN_W; x++) {
            uint16_t c = src[x];
            if (c != 0) {
                dst[x] = c;
            }
        }
    }

    // Central bulkhead armored plate (clean diegetic metal)
}

void wall_draw_turret_sprite(uint16_t *buffer, int dest_x, int dest_y, int angle_idx) {
    if (!buffer || angle_idx < 0 || angle_idx >= WALL_TURRET_ANGLE_COUNT) return;
    const uint16_t *src = c_turret_frames[angle_idx];
    for (int y = 0; y < TURRET_SPRITE_H; y++) {
        int py = dest_y + y;
        if (py < 0 || py >= SCREEN_H) continue;
        uint16_t *dst_row = &buffer[py * SCREEN_W];
        const uint16_t *src_row = &src[y * TURRET_SPRITE_W];
        for (int x = 0; x < TURRET_SPRITE_W; x++) {
            int px = dest_x + x;
            if (px < 0 || px >= SCREEN_W) continue;
            uint16_t color = src_row[x];
            if (color != 0) {
                dst_row[px] = color;
            }
        }
    }
}


